```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

#define LOOPS 100000

long shared_counter = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *incrementer(void *arg) {
    int use_mutex = *(int *)arg;
    for (int i = 0; i < LOOPS; i++) {
        if (use_mutex) {
            pthread_mutex_lock(&mutex);
        }

        long temp = shared_counter;
        shared_counter = temp + 1;

        if (use_mutex) {
            pthread_mutex_unlock(&mutex);
        }
    }
    return NULL;
}

int main(void) {
    pthread_t t1, t2;
    int use_mutex = 0;

    // 1. Race condition run (without mutex)
    pthread_create(&t1, NULL, incrementer, &use_mutex);
    pthread_create(&t2, NULL, incrementer, &use_mutex);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    printf("Without mutex counter: %ld (Expected: %d)\n", shared_counter, 2 * LOOPS);

    // 2. Fixed run (with mutex)
    shared_counter = 0;
    use_mutex = 1;
    pthread_create(&t1, NULL, incrementer, &use_mutex);
    pthread_create(&t2, NULL, incrementer, &use_mutex);
    pthread_join(t1, NULL);
    pthread_join(t2, NULL);
    printf("With mutex counter: %ld (Expected: %d)\n", shared_counter, 2 * LOOPS);

    pthread_mutex_destroy(&mutex);
    return 0;
}
```

### Explanation
- **Mutual Exclusion**: When `use_mutex = 1`, `pthread_mutex_lock` ensures that only one thread enters the critical section at a time, preventing overlapping updates to `shared_counter`.
- **Progress**: If no thread is in the critical section, a thread wanting entry will succeed without arbitrary delay.
- **No Deadlock**: A single mutex prevents circular wait conditions.
- **No Lost Wakeups**: No condition variables are used here, so no wakeup signals can be missed.

### Compile and Test
```bash
gcc -Wall -pthread prog.c -o prog
./prog
gcc -fsanitize=thread -g -Wall -pthread prog.c -o prog_tsan
./prog_tsan
```

